'use strict';
const test=require('node:test'), assert=require('node:assert/strict');
const fs=require('node:fs'), os=require('node:os'), path=require('node:path');
const B=require('../../tests/support/browser.cjs');
const evidence=path.join(os.tmpdir(),'acc-det130-process-cost-explorer');
const base=(B.browserURL||'').replace(/\/+$/,'');
const lesson=base+'/materials-and-processes/manufacturing-cost-and-volume.html';
// Optional read-only browser fixture: exact generated bytes, no HTTP listener or external requests.
async function fixture(context) {
  const root=process.env.COURSEWIKI_FIXTURE_ROOT;
  if(!root) return;
  const origin=new URL(base).origin;
  await context.route('**/*',async route=>{
    const url=new URL(route.request().url());
    if(url.origin!==origin) return route.abort();
    const segments=decodeURIComponent(url.pathname).split('/').filter(Boolean);
    if(url.pathname.endsWith('/')) segments.push('index.html');
    let file=root;
    for(const segment of segments) {
      if(segment==='.'||segment==='..'||!fs.readdirSync(file).includes(segment)) return route.fulfill({status:404,body:'Case-exact fixture: not found'});
      file=path.join(file,segment);
    }
    const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml','.png':'image/png','.webp':'image/webp','.ico':'image/x-icon','.woff2':'font/woff2'};
    return route.fulfill({status:200,contentType:types[path.extname(file)]||'application/octet-stream',body:fs.readFileSync(file)});
  });
}
async function open(page,present=false) {
  await fixture(page.context());
  const response=await page.goto(lesson+(present?'?p=det-130&present=1':''));
  assert.equal(response.status(),200);
  await page.evaluate(()=>document.querySelectorAll('details.xcard').forEach(n=>n.open=true));
  await page.locator('.pb-live').waitFor();
}
async function compare(page,prediction) {
  const lab=page.locator('.pb-live').first();
  await lab.locator('[data-pb="prediction"]').selectOption(prediction);
  await lab.locator('[data-pb-compare]').click();
}
test('prediction, cases, exact cents, invalid clearing, keyboard and responsive themes', {skip:B.skip}, async()=>{
  fs.mkdirSync(evidence,{recursive:true});
  const browser=await B.launch();
  try {
    for(const width of [1280,390,375]) for(const theme of ['light','dark']) for(const present of [false,true]) {
      const context=await browser.newContext({viewport:{width,height:1000},colorScheme:theme});
      const page=await context.newPage(), errors=[];
      page.on('pageerror',e=>errors.push(String(e)));
      await open(page,present);
      await page.evaluate(t=>document.documentElement.dataset.theme=t,theme);
      const lab=page.locator('.pb-live'), field=k=>lab.locator('[data-pb="'+k+'"]');
      const status=lab.locator('[data-pb-feedback]'), results=lab.locator('[data-pb-results]');
      assert.equal(await results.isVisible(),false);
      await lab.locator('[data-pb-compare]').focus(); await page.keyboard.press('Enter');
      assert.match(await status.textContent(),/Choose a prediction before/);
      assert.equal(await field('prediction').evaluate(n=>n===document.activeElement),true);
      await field('prediction').selectOption('tie');
      await lab.locator('[data-pb-compare]').focus(); await page.keyboard.press('Enter');
      assert.match(await status.textContent(),/Prediction matches.*exact total costs are equal/);
      assert.match(await lab.locator('[data-pb-totals]').textContent(),/1,080.00 total/);
      assert.match(await lab.locator('[data-pb-crossing]').textContent(),/= 120 parts/);
      assert.equal(await lab.locator('tbody tr').count(),3);
      await field('quantity').fill('60');
      assert.equal(await results.isVisible(),false); assert.equal(await lab.locator('svg').count(),0);
      assert.equal(await field('prediction').inputValue(),'');
      await compare(page,'B'); assert.match(await status.textContent(),/Prediction differs.*A.*300.00/);
      await field('slider').focus(); await page.keyboard.press('ArrowRight');
      assert.equal(await field('quantity').inputValue(),'61'); assert.equal(await results.isVisible(),false);
      await field('scenario').selectOption('fractional'); await compare(page,'B');
      assert.match(await lab.locator('[data-pb-crossing]').textContent(),/38.75.*no whole-part tie/);
      assert.match(await lab.locator('tbody').textContent(),/38.*318.00.*321.00.*A.*39.*324.00.*323.00.*B/s);
      for(const [scenario,prediction,pattern] of [
        ['parallel','A',/parallel.*no crossing/s],['dominated','A',/No positive crossing/],
        ['tie','tie',/All-Q tie/],['beyond','A',/1,600.*beyond.*does not mean none/s]]) {
        await field('scenario').selectOption(scenario); await compare(page,prediction);
        assert.match(await lab.locator('[data-pb-crossing]').textContent(),pattern);
      }
      await field('quantity').fill('1601'); await compare(page,'B');
      assert.match(await lab.locator('[data-pb-caption]').textContent(),/1,601 is outside this chart/);
      assert.equal(await field('slider').isDisabled(),true);
      for(const [key,value] of [['quantity',''],['quantity','0'],['quantity','1.5'],['quantity','10001'],['fixedA','-1'],['variableB','0.001']]) {
        await field('scenario').selectOption('original'); await compare(page,'tie');
        await field(key).fill(value);
        assert.match(await status.textContent(),/No comparison/);
        assert.equal(await results.isVisible(),false); assert.equal(await lab.locator('svg').count(),0);
        assert.equal(await lab.locator('[data-result]').textContent(),'');
        assert.equal(await field(key).getAttribute('aria-invalid'),'true');
      }
      await field('scenario').selectOption('original');
      for(const [key,value] of Object.entries({fixedA:'0',fixedB:'.01',variableA:'1',variableB:'1',quantity:'10000'})) await field(key).fill(value);
      await compare(page,'A'); assert.match(await status.textContent(),/Prediction matches.*0.01/);
      assert.equal((await lab.locator('[data-pb-totals]').textContent()).match(/\$1.0000/g).length,2);
      assert.match(await lab.textContent(),/rounded averages do not decide a tie/);
      await field('scenario').selectOption('fractional'); await compare(page,'B');
      const overflow=()=>page.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1 || [...document.querySelectorAll('.pb-live, .pb-live input, .pb-live select, .pb-live button, #pb-control')].some(n=>{const r=n.getBoundingClientRect();return r.width>0&&(r.left < -1||r.right>innerWidth+1);}));
      assert.equal(await overflow(),false,width+' '+theme+' '+present+' overflow');
      await page.evaluate(()=>{const n=document.createElement('div');n.id='pb-control';n.style.width='2000px';document.body.append(n);});
      assert.equal(await overflow(),true); await page.locator('#pb-control').evaluate(n=>n.remove()); assert.equal(await overflow(),false);
      await lab.screenshot({path:path.join(evidence,width+'-'+theme+'-'+(present?'present':'read')+'.png')});
      assert.deepEqual(errors,[]);
      await context.close();
    }
  } finally {await browser.close();}
});
test('native Space activates Compare in reading and presentation', {skip:B.skip},async()=>{
  const browser=await B.launch();
  try {
    for(const present of [false,true]) {
      const page=await browser.newPage(); await open(page,present);
      await page.locator('[data-pb="prediction"]').selectOption('tie');
      await page.locator('[data-pb-compare]').focus(); await page.keyboard.press('Space');
      assert.match(await page.locator('[data-pb-feedback]').textContent(),/Prediction matches/,'native Space; present='+present);
      await page.close();
    }
  } finally {await browser.close();}
});
test('independent roots, idempotent binding, original routes and native practice', {skip:B.skip},async()=>{
  const browser=await B.launch();
  try {
    const page=await browser.newPage(); await open(page);
    await page.evaluate(()=>{
      const source=document.querySelector('[data-interactive="process-break-even"]');
      const root=document.createElement('div'); root.dataset.interactive='process-break-even';
      root.append(source.querySelector('.pb-static').cloneNode(true)); source.after(root);
    });
    const script=fs.readFileSync(path.join(__dirname,'demo.js'),'utf8');
    await page.addScriptTag({content:script}); await page.addScriptTag({content:script});
    assert.equal(await page.locator('.pb-live').count(),2);
    const labs=page.locator('.pb-live');
    await labs.nth(0).locator('[data-pb="quantity"]').fill('60');
    await labs.nth(0).locator('[data-pb="prediction"]').selectOption('A');
    await labs.nth(0).locator('[data-pb-compare]').click();
    assert.equal(await labs.nth(1).locator('[data-pb="quantity"]').inputValue(),'120');
    assert.equal(await labs.nth(1).locator('[data-pb-results]').isVisible(),false);
    const headings=['count-material-processing-quality-and-overhead-costs-once','spread-fixed-cost-over-the-quantity-actually-needed','set-total-costs-equal-to-find-process-break-even','move-the-volume-slider-and-predict-which-process-wins'];
    for(const id of headings) assert.equal(await page.locator('[id="'+id+'"]').count(),1);
    const href=await page.locator('a[href="../practice.html#economics-break-even"]').getAttribute('href');
    const response=await page.goto(new URL(href,lesson).href); assert.equal(response.status(),200);
    const panel=page.locator('#economics-break-even');
    await panel.locator('[data-practice-input]').fill('150'); await panel.locator('[data-practice-check]').click();
    assert.match(await panel.locator('[data-practice-feedback]').textContent(),/Correct/);
    await panel.locator('[data-practice-input]').fill('57.69'); await panel.locator('[data-practice-check]').click();
    assert.match(await panel.locator('[data-practice-feedback]').textContent(),/Not yet/);
  } finally {await browser.close();}
});
test('static no-JavaScript and self-contained offline aggregate preserve the lesson', {skip:B.skip},async()=>{
  fs.mkdirSync(evidence,{recursive:true}); const browser=await B.launch();
  try {
    const context=await browser.newContext({javaScriptEnabled:false,viewport:{width:390,height:900}}), page=await context.newPage();
    await fixture(context);
    assert.equal((await page.goto(lesson)).status(),200);
    assert.match(await page.locator('.pb-static').textContent(),/38.75.*No whole-part quantity ties/s);
    assert.equal(await page.locator('.pb-live').count(),0);
    await page.pdf({path:path.join(evidence,'lesson-nojs.pdf'),format:'Letter',margin:{top:'.5in',bottom:'.5in',left:'.5in',right:'.5in'}});
    await context.close();
    const offline=await browser.newContext(), aggregate=await offline.newPage();
    const generatedRoot=process.env.COURSEWIKI_FIXTURE_ROOT||path.join(__dirname,'../../docs');
    await aggregate.route('http://offline.test/**',route=>route.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(path.join(generatedRoot,'print/track-det-130.html'),'utf8')}));
    const errors=[]; aggregate.on('pageerror',e=>errors.push(String(e)));
    await aggregate.goto('http://offline.test/track-det-130.html');
    await aggregate.evaluate(()=>document.querySelectorAll('details.xcard').forEach(n=>n.open=true));
    await aggregate.locator('.pb-live').waitFor();
    await compare(aggregate,'tie');
    assert.match(await aggregate.locator('.pb-live [data-pb-feedback]').textContent(),/Prediction matches/);
    assert.deepEqual(errors,[]);
    await aggregate.emulateMedia({media:'print'});
    assert.equal(await aggregate.locator('.pb-live').isVisible(),false);
    assert.equal(await aggregate.locator('.pb-static').isVisible(),true);
    await offline.close();
  } finally {await browser.close();}
});
